styles.css:
position: relative;
overflow: hidden;
align-items: center;
max-inline-size: 24.167rem;
text-align: center;
transform-origin: top center;

& .ls-card__icon-shell {
	align-self: center;
}

& .ls-card-services__content {
	display: flex;
	flex: 1 1 auto;
	flex-direction: column;
	align-items: center;
	gap: var(--wp--preset--spacing--20);
	inline-size: 100%;
}

& .ls-card-services__content > * {
	margin-block: 0;
}

& .ls-card-services__list {
	inline-size: 100%;
	margin-block: 0;
}

& .ls-card-services__cta {
	position: static;
	margin-top: auto;
	margin-bottom: 0;
}

& .ls-card-services__cta a::before {
	content: "";
	position: absolute;
	inset: 0;
	z-index: 1;
}

& .ls-card-services__cta a {
	position: relative;
	z-index: 2;
}

& .ls-card-services__cta a::after {
	position: relative;
	z-index: 2;
}
